    post({"jsonrpc":"2.0","method":"notifications/initialized"},h)
    for method in ["tools/list","resources/list","prompts/list"]:
        st,hd,body=post({"jsonrpc":"2.0","id":2,"method":method},h)
        print("==",method,st)
