  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"e43b7c0d-b469-4c27-8991-6337a5d6d1eb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、法律依据（初步）\"}}]}}, {\"object\": \"block\", \"id\": \"65f6b39d-b582-4260-860c-ccc5d50f9518\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第97条：进口预包装食品应当有中文标签、中文说明书，载明原产地及境内代理商名称、地址、联系方式；没有中文标签、中文说明书的不得进口。\"}}]}}, {\"object\": \"block\", \"id\": \"314ac3e3-5403-48c1-8ba1-2ace8a724e06\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第34条：禁止生产经营无标签的预包装食品、添加食品添加剂以外化学物质或其他可能危害人体健康物质的食品。\"}}]}}, {\"object\": \"block\", \"id\": \"652668e6-e6ca-47cc-8257-82b33d372170\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第148条：经营明知不符合食品安全标准的食品，消费者可要求退款并主张价款十倍或损失三倍赔偿，不足1000元按1000元计；但标签、说明书存在“不影响食品安全且不会误导”的瑕疵除外。\"}}]}}, {\"object\": \"block\", \"id\": \"cbde6204-d969-4f00-8a15-655c3c4ca085\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《消费者权益保护法》第44条：平台不能提供销售者真实名称、地址、有效联系方式的，消费者可向平台索赔；平台明知/应知侵权未采取必要措施的，承担连带责任。\"}}]}}, {\"object\": \"block\", \"id\": \"914c6d9c-02d5-4221-8e23-161ffc20c698\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《消费者权益保护法》第55条：普通消费欺诈为价款三倍（保底500元）。食品不安全优先适用《食品安全法》第148条十倍，不重复主张。\"}}]}}, {\"object\": \"block\", \"id\": \"5416a7e8-f7cb-4aaa-88f4-b87aa4c68ca9\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"最高法食品药品纠纷规定第3条（经 (2025)沪01民终05600号确认）：食品、药品领域，销售者以购买者“明知有问题仍购买”抗辩的，法院不予支持。\"}}]}}, {\"object\": \"block\", \"id\": \"ebc2dd7a-d4a0-4655-8062-3c19781eb5f0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、可以主张什么（初步方案）\"}}]}}, {\"object\": \"block\", \"id\": \"6ce8cdb8-66e9-4740-89a2-172eeb248a03\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"1）退还货款 1,880 元：两件商品均不符合食品安全标准，可要求退货退款。\"}}]}}, {\"object\": \"block\", \"id\": \"1918ad70-80b1-40c4-8a46-d8a557c75d7b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"2）惩罚性赔偿 18,800 元：按价款十倍（1,880×10）。若法院按单品拆分，奶粉 680×10=6,800，茶 1,200×10=12,000，合计相同。退一赔十合计 20,680 元。\"}}]}}, {\"object\": \"block\", \"id\": \"ee103560-b7e0-4192-8e40-c151b956f44b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"3）医疗费 320 元及合理交通费：实际损失，另行主张；不并入十倍基数。\"}}]}}, {\"object\": \"block\", \"id\": \"574401af-74b8-4d01-8a15-115d9ecf7731\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"4）检验费（实际发生，预算≤3,000 元）：先由赵萌垫付，诉请由被告承担。\"}}]}}, {\"object\": \"block\", \"id\": \"0ea5f9ae-d7cc-4b77-872b-a6c00087155c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"5）精神损害抚慰金 20,000 元：不建议作为主诉请求。一般需“严重精神损害”后果，320 元急诊较难达到；可留作谈判筹码，但别让法官觉得漫天要价。\"}}]}}, {\"object\": \"block\", \"id\": \"6419daf5-9dfc-47e7-8ae9-845dec33a27f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"6）平台责任：目前卖家主体信息明确，暂不列优鲜购为被告；但应书面投诉并保留平台回复。若卖家失联或平台拒不提供资质，再依《消保法》第44条追加平台。\"}}]}}, {\"object\": \"block\", \"id\": \"fd63287f-4f08-4a3c-8e22-74a6ba7c67f2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、风险与应对\"}}]}}, {\"object\": \"block\", \"id\": \"a325d411-2754-41c3-8926-474b506bec84\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"卖家说“知假买假、职业打假”：不成立。食品领域明确规定该抗辩不支持（(2025)沪01民终05600号）。且各买 1 件属合理生活消费，不属于大额囤购（对比 (2024)浙0110民初18700号）。\"}}]}}, {\"object\": \"block\", \"id\": \"03ab66aa-ec14-4d41-80ae-fbd93b9a6d12\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“标签瑕疵”例外：例外仅限不影响食品安全且不误导的轻微瑕疵。整罐无中文标签，消费者无法知悉成分、保质期、境内代理商，不属于轻微瑕疵（(2025)沪0112民初18900号）。对比仅字号问题的 (2025)沪0112民初16800号。\"}}]}}, {\"object\": \"block\", \"id\": \"e08e7f73-4603-46e0-82df-1e777eb4e8aa\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"茶的功效宣传：普通食品宣称治疗高血压、降血糖，且无保健食品批号，法院有支持十倍的先例（(2025)沪0112民初15800号）。即使未检出非法添加，也可依标签/宣传违规主张。\"}}]}}, {\"object\": \"block\", \"id\": \"b0398e52-5da9-4c77-8546-b014c766b74b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"非法添加：需检验报告支撑。检出西布曲明等非食用物质，直接构成不符合食品安全标准（(2025)沪0115民初20300号）。若未检出，不影响奶粉无中文标签的十倍主张。\"}}]}}, {\"object\": \"block\", \"id\": \"b5dbd87b-6fe3-4444-82d7-57c2e7acfe75\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十倍基数争议：若法院认为茶仅为宣传欺诈、不构成食品安全问题，备选请求为奶粉十倍 6,800 元 + 茶按消法三倍 3,600 元（1,200×3），合计 10,400 元；庭审中作为备位主张提出。\"}}]}}, {\"object\": \"block\", \"id\": \"c4ecee2a-e867-4c01-8e53-151cbefdf174\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"检验报告被采信：必须选有 CMA（最好 CNAS）资质的食品检验机构，且独立于卖家；无资质报告不采信（(2025)沪01民终06100号）。拒绝“保证检出/按结果收费”。\"}}]}}, {\"object\": \"block\", \"id\": \"7b4b0e40-0865-446c-8891-e9287c843b12\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据保全：商品继续原样封存，不要拆封或丢弃；开箱视频保留原始文件与拍摄时间；聊天记录做完整导出，不只截片段。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

