  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"8751e076-864b-4a8d-8ba9-9379266908fd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"七、类似判例（已检索并存入法律检索库）\"}}]}}, {\"object\": \"block\", \"id\": \"2765dfb4-03c3-4b78-88f8-c3d23833fa17\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"说明：检索库里原先没有你收藏的判例；以下 9 篇是与本案最相关的公开判例，已存入你的收藏并逐篇加了备注。\"}}]}}, {\"object\": \"block\", \"id\": \"3343b196-b077-4884-83ca-8594cb8c270a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"① (2025)沪0112民初18900号（上海闵行法院）：进口预包装食品整罐无中文标签，属不符合食品安全标准，支持价款十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"2cd85de6-818f-4ae1-841a-556a778c8606\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"② (2025)沪0112民初15800号（上海闵行法院）：普通食品无保健食品批号却宣称治疗高血压、降糖，支持十倍赔偿。\"}}]}}, {\"object\": \"block\", \"id\": \"588894a3-9684-477c-80cb-cfed11cb539e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"③ (2025)沪01民终05600号（上海一中院）：食品领域“知假买假”不影响十倍索赔，销售者抗辩被驳回。\"}}]}}, {\"object\": \"block\", \"id\": \"69d97b37-92d0-4e40-8496-fe03afdbe9be\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"④ (2025)沪0115民初20300号（上海浦东法院）：代用茶检出非法添加物（西布曲明等），支持价款十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"5ec6a4bd-dd04-4d7e-8e1f-304b0b231778\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑤ (2025)沪01民终06100号（上海一中院）：无 CMA/CNAS 资质机构出具的检验报告不被采信。\"}}]}}, {\"object\": \"block\", \"id\": \"d9343e16-6954-407f-8a53-cd9a76f4b114\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_lis