  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"12304875-c9eb-43df-8989-912042401473\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"📌\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一句话案情：2026-04-18 在优鲜购「环球优选」店花 1880 元买进口奶粉 1 罐（680 元）+ 养生代用茶 1 盒（1200 元）。奶粉整罐无中文标签；茶是普通食品却宣称治高血压、降血糖，饮用后心慌就医（自费 320 元）。卖家只同意退货退款，拒绝赔偿。拟按《食品安全法》第148条主张退一赔十。\"}}]}}, {\"object\": \"block\", \"id\": \"f8163f77-4e72-4ced-8fa7-3e7298cff242\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一、当事人与管辖\"}}]}}, {\"object\": \"block\", \"id\": \"899b513d-5357-46f3-8788-0074f8cea668\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"消费者（原告）：赵萌，收货地上海市浦东新区。\"}}]}}, {\"object\": \"block\", \"id\": \"1bbce61e-f85f-4b76-882b-6c8487197c9a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"销售者（第一被告）：杭州环球优选食品有限公司，住所地浙江省杭州市余杭区。\"}}]}}, {\"object\": \"block\", \"id\": \"aae187a4-3d5b-4d07-8a04-7782ba0b9145\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"平台：优鲜购商城，经营者上海优鲜购网络科技有限公司（是否列被告视卖家应诉/平台过错而定）。\"}}]}}, {\"object\": \"block\", \"id\": \"17dee9cb-4156-44ac-85***\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"管辖：上海市浦东新区人民法院。网络购物合同以收货地为合同履行地，可在收货地起诉（参考 (2025)沪0112民初16200号）。标的额小，适用基层法院简易程序。\"}}]}}, {\"object\": \"block\", \"id\": \"39ff8d78-3ea9-4c57-844e-df27959dce9d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼时效：3 年，自 2026-04-22 收货发现问题起算，至 2029-04-22 届满。\"}}]}}, {\"object\": \"block\", \"id\": \"9ee13c08-cc49-4ba4-8e9a-5a9453bcf96a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false,