    try:
        r=urllib.request.urlopen(req,timeout=15); return dict(r.headers),r.read().decode()
    except urllib.error.HTTPError as e: return dict(e.headers),e.read().decode()
h={'Content-Type':'application/json','Accept':'application/json, text/event-stream'}
