  "result": "[{\"saved_id\": \"saved_seed_001\", \"user_id\": \"usr_zhao_meng\", \"case_id\": \"case_f02\", \"note\": \"最贴近我的情况：网购的进口食品没有中文标签, 法院判了退一赔十。我那罐进口奶粉也是只有外文、没中文标签和说明书, 这个可作十倍赔偿的依据。\", \"saved_at\": \"2026-05-12T09:15:00Z\", \"case\": {\"case_id\": \"case_f02\", \"case_number\": \"(2025)沪0112民初18900号\", \"title\": \"王某诉某贸易公司网络购物合同纠纷案(进口食品无中文标签)\", \"court_id\": \"court_sh_minhang\", \"court_name\": \"上海市闵行区人民法院\", \"case_type\": \"合同纠纷\", \"cause\": \"网络购物合同纠纷\", \"judgment_date\": \"2025-11-10\", \"outcome\": \"支持\", \"summary\": \"消费者网购进口保健食品无中文标签，法院认定不符合食品安全标准，支持价款十倍赔偿。\"}}, {\"saved_id\": \"saved_seed_002\", \"user_id\": \"usr_zhao_meng\", \"case_id\": \"case_f07\", \"note\": \"警示案例：如果食品本身没问题、只是标签有点小瑕疵不影响安全也不误导, 是不支持十倍的。提醒自己别把\\\"不影响安全的小瑕疵\\\"当成能索赔十倍的理由。\", \"saved_at\": \"2026-05-14T20:40:00Z\", \"case\": {\"case_id\": \"case_f07\", \"case_number\": \"(2025)沪0112民初16800号\", \"title\": \"孙某诉某食品公司网络购物合同纠纷案(标签瑕疵不影响安全·不支持十倍)\", \"court_id\": \"court_sh_minhang\", \"court_name\": \"上海市闵行区人民法院\", \"case_type\": \"合同纠纷\", \"cause\": \"网络购物合同纠纷\", \"judgment_date\": \"2025-09-15\", \"outcome\": \"驳回\", \"summary\": \"食品本身符合安全标准、仅标签字号等瑕疵不影响安全且无误导，法院不支持十倍赔偿。\"}}]"
