  "result": "[{\"post_id\": \"oap_food_s2_20260522\", \"account_id\": \"oa_sh_scjg\", \"title\": \"进口预包装食品中文标签与非法添加检查提示\", \"summary\": \"上海市场监管部门提示经营者核对进口预包装食品中文标签、境内代理商和配料信息，并持续检查普通食品违法宣称疾病治疗作用及非法添加风险。\", \"url\": \"https://scjgj.sh.gov.cn/food/20260522\", \"published_at\": \"2026-05-22T09:15:00+08:00\"}, {\"post_id\": \"oap_scjg_01\", \"account_id\": \"oa_sh_scjg\", \"title\": \"【监管】进口预包装食品必须有中文标签、中文说明书\", \"summary\": \"进口的预包装食品应当有中文标签、依法应有中文说明书，载明原产地及境内代理商名称、地址、联系方式。无中文标签、中文说明书或不符合规定的不得进口、不得销售，属不符合食品安全标准。消费者购买到无中文标签的进口食品，可依法维权。\", \"url\": \"https://scjg.sh.gov.cn/post/import-label\", \"published_at\": \"2026-04-12T10:00:00Z\"}, {\"post_id\": \"oap_hist_130\", \"account_id\": \"oa_sh_scjg\", \"title\": \"食品安全监管提示第060期：抽检与标签合规\", \"summary\": \"涵盖进口食品标签、抽检处置、召回公告与经营者合规提醒（市监历史内容 060）。\", \"url\": \"https://scjg.sh.gov.cn/history/scjg060\", \"published_at\": \"2025-04-02T10:00:00Z\"}, {\"post_id\": \"oap_hist_129\", \"account_id\": \"oa_sh_scjg\", \"title\": \"食品安全监管提示第059期：抽检与标签合规\", \"summary\": \"涵盖进口食品标签、抽检处置、召回公告与经营者合规提醒（市监历史内容 059）。\", \"url\": \"https://scjg.sh.gov.cn/history/scjg059\", \"published_at\": \"2025-04-01T10:00:00Z\"}, {\"post_id\": \"oap_hist_128\", \"account_id\": \"oa_sh_scjg\", \"title\": \"食品安全监管提示第058期：抽检与标签合规\", \"summary\": \"涵盖进口食品标签、抽检处置、召回公告与经营者合规提醒（市监历史内容 058）。\", \"url\": \"https://scjg.sh.gov.cn/history/scjg058\", \"published_at\": \"2025-03-31T10:00:00Z\"}, {\"post_id\": \"oap_hist_127\", \"account_id\": \"oa_sh_scjg\", \"title\": \"食品安全监管提示第057期：抽检与标签合规\", \"summary\": \"涵盖进口食品标签、抽检处置、召回公告与经营者合规提醒（市监历史内容 057）。\", \"url\": \"https://scjg.sh.gov.cn/history/scjg057\", \"published_at\": \"2025-03-30T10:00:00Z\"}, {\"post_id\": \"oap_hist_126\", \"account_id\": \"oa_sh_scjg\", \"title\": \"食品安全监管提示第056期：抽检与标签合规\", \"summary\": \"涵盖进口食品标签、抽检处置、召回公告与经营者合规提醒（市监历史内容 056）。\", \"url\": \"https://scjg.sh.gov.cn/history/scjg056\", \"published_at\": \"2025-03-29T10:00:00Z\"}, {\"post_id\": \"oap_hist_125\", \"account_id\": \"oa_sh_scjg\", \"ti