{
  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"5c2e59e6-cecd-47bf-815e-1ca8675e549c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十四、检验机构筛选（2026-05-22）\"}}]}}, {\"object\": \"block\", \"id\": \"4bb31809-a436-4bb9-87d7-e160dfb94b8b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"筛选标准（按你邮件 #7）：①总费用≤3,000 元；②只测标签符合性+非法添加，不买全项套餐；③有食品检验 CMA（最好 CNAS），报告能在上海法院采信；④独立，与卖家无关联；⑤不接受“保证检出/按结果收费”。\"}}]}}, {\"object\": \"block\", \"id\": \"4ca3e5f2-902c-457c-8e0f-a4759bef0a50\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-001 恒康检测：✗ 不能选。CMA、¥2200/项，但与被告卖家同一实际控制人，且长期为卖家做出厂检验，独立性存疑（违反④）。\"}}]}}, {\"object\": \"block\", \"id\": \"1dcac41b-4c01-45cd-88ae-eb9471485ba7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-002 京衡检测：✗ 不能选。CMA 能力范围不含进口食品标签符合性和非法添加项，实验室在北京，上海标的项目不在认可范围（违反②③）。\"}}]}}, {\"object\": \"block\", \"id\": \"b286149a-ce64-462c-8c42-0f3754df80cb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-003 诚信咨询：✗ 不能选。只是检测咨询公司，没有食品检验 CMA，报告不能作为认定食品是否安全的依据（违反③）。\"}}]}}, {\"object\": \"block\", \"id\": \"c17e16b1-5bc3-4ea0-8376-093f4d75c256\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-004 宏远检测：✗ 不能选。按“结果是否对委托方有利”浮动收费，还承诺“保证检出不合格、检不出不收费”，违反独立客观原则，报告不被法院采信（违反⑤）。\"}}]}}, {\"object\": \"block\", \"id\": \"919b35a5-2085-48f7-8de2-50f8690d53db\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-005 大正检测：✗ 不能选。CMA+CNAS，但只接全项套餐，起步 ¥6000/单且全额预付，不接受单项委托，超预算且没必要（违反①②）。\"}}]}}, {\"object\": \"block\", \"id\": \"42de92d1-6f12-4533-81fa-499388cbe00b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-006 沪正检测：✓ 推荐。CMA+CNAS；范围含进口食品标签符合性、非法添加物筛查；报告可用于上海法院诉讼；固定 ¥2000/项，不与结果挂钩；独立第三方，与双方无利益关联。五项全部满足。\"}}]}}, {\"object\": \"block\", \"id\": \"199bf798-7c00-42cb-8ff9-9a4da199d1ed\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-007 天合检测：✗ 不能选。CMA 资质因出具虚假报告被暂停，暂停期不得对外出报告（违反③，绝对不能选）。\"}}]}}, {\"object\": \"block\", \"id\": \"8d9de53c-9676-4237-8aa7-6df2b376b36d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-008 申瑞检测：✓ 备选。CMA；范围含进口食品标签符合性与非法添加筛查；报告可用于上海法院；固定 ¥2800/项，不与结果挂钩；独立。也合规，但比沪正贵 800 元且没有 CNAS，优先级排第二。\"}}]}}, {\"object\": \"block\", \"id\": \"ea5a3351-c86b-40fe-86cf-540a87784069\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"✅\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"推荐：JY-006 沪正检测技术有限公司（¥2000/项，CMA+CNAS）。备选：JY-008 申瑞检测（¥2800/项，CMA）。预约页面：https://inspect.sh.gov.cn/JY-006\"}}]}}, {\"object\": \"block\", \"id\": \"125cbef3-4f64-46c4-8821-362524163a01\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"预算怎么卡在 3000 以内\"}}]}}, {\"object\": \"block\", \"id\": \"1d0081a5-b433-4895-8a1c-5c30f5073013\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果“项”是按检验项目计费：奶粉标签 + 茶非法添加两项 = 4000 元，超预算。建议只把茶送检，做“标签符合性 + 非法添加筛查”一个委托（2000 元）；奶粉无中文标签用实物、正反面照片、开箱视频和市监局公告证明即可，标签有没有中文是肉眼可查的事实，不必再花 2000 元做检测。若律师坚持奶粉也出报告，先让沪正报两项打包价并压到 3000 以内；谈不下来就先做茶，奶粉用现有证据。\"}}]}}, {\"object\": \"block\", \"id\": \"4d5a1e1e-5b5d-4c1d-8e39-d0d1c239044a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"委托前必须核对\"}}]}}, {\"object\": \"block\", \"id\": \"2801e6bd-04f4-4f72-8a5c-934b7f8ad137\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"看 CMA 证书及附表：确认“进口食品标签符合性”“非法添加物”在能力范围；有 CNAS 更好。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"f3b106d0-22bd-4943-88f4-ab80f4ed73ee\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"书面确认固定价、不与结果挂钩、不承诺“保证检出”；报告盖 CMA 章、可用于上海法院。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"c4784321-f702-44bf-8511-352da115d2c2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"确认与杭州环球优选食品有限公司无股权、业务关联（企查查/股权穿透截图留存）。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"f09fffbc-f69d-4c02-80f8-a6e609c31202\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"送检前对未拆封样品拍照录像，要求机构封样并出具收样单；保留付款凭证和发票。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"ed926406-1bb9-47ea-884d-597d69c9ac18\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十五、判例精读（与你情况最像的 7 篇）\"}}]}}, {\"object\": \"block\", \"id\": \"e8454d0b-c0f7-4748-80cb-d5576d207350\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"① (2025)沪0112民初18900号：1,200 元进口保健食品整罐无中文标签，法院依《食品安全法》第97条认定不符合安全标准，判退 1,200 + 赔 12,000。关键句：无中文标签使消费者无法知悉成分、保质期，不属于“不影响安全的轻微瑕疵”。你的奶粉直接套用。\"}}]}}, {\"object\": \"block\", \"id\": \"c7b7deb1-21dd-4d3a-8112-75051f7d7bc0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"② (2025)沪0112民初16800号：食品本身合格，仅标签字号偏小、标点错误，法院不支持十倍。这是你收藏的警示案例；但你的奶粉是“整罐没有中文标签”，不是字号问题，不适用这个除外规则。\"}}]}}, {\"object\": \"block\", \"id\": \"4a54fe05-d360-4900-8b27-d57d87eb4a58\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"③ (2025)沪0115民初20300号：2,000 元代用茶检出西布曲明等非食用物质，法院依第34条、第148条判退 2,000 + 赔 20,000。关键：非法添加靠检验报告；若沪正检出，茶的十倍请求直接落地。\"}}]}}, {\"object\": \"block\", \"id\": \"016de23a-6286-45b1-8c40-a5345b8211ee\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"④ (2025)沪0112民初15800号：普通食品无保健食品批号，却在页面宣称“治疗高血压、降糖”，法院支持十倍。关键：即使茶检不出非法添加，功效宣称本身也能支撑十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"5bfb0688-279d-428e-8e5b-573934e30c8e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑤ (2025)沪01民终06100号：一方自行委托无 CMA/CNAS 资质机构出的报告不被采信，应以有资质机构检验为准。这就是为什么不能贪便宜找 JY-003/JY-004。\"}}]}}, {\"object\": \"block\", \"id\": \"46bf8162-ebb6-4d0a-82ce-a5eda7ee15e2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑥ (2025)沪0112民初15300号：消费者保留未拆封实物、订单、支付、聊天、开箱视频，证据充分获支持；反之举证不能。你的“原样封存、不寄回”就是按这个判例在做。\"}}]}}, {\"object\": \"block\", \"id\": \"acc16b34-b520-4cc0-8948-d7f48c3af0b3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑦ (2025)沪0115民初20100号：进口食品无入境货物检验检疫证明、来源不明，法院认定不能证明符合我国食品安全标准，支持十倍。可书面要求卖家/平台出示奶粉的检验检疫证明；拿不出来对你有利。\"}}]}}, {\"object\": \"block\", \"id\": \"bf8317af-a11d-42f1-8133-451901203542\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🧭\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"结论：你的案子有两条腿。奶粉靠“无中文标签”（判例①②⑦）；茶靠“非法添加检验”（判例③）或“普通食品宣称疗效”（判例④）。即使茶检不出非法添加，茶仍可按功效宣称主张十倍，奶粉的十倍不受影响。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

