{
  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"800eb3e9-61e4-4968-854f-6d56cab4e457\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十六、诉讼请求逐条审查（2026-05-23）\"}}]}}, {\"object\": \"block\", \"id\": \"b4132b5b-cf1a-4a38-8e66-9a2885c244bb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"对照你邮件 #6 的六笔账：3 项可以一起主张，1 项建议不提，1 项暂时保留，1 项不是诉讼请求而是抗辩。\"}}]}}, {\"object\": \"block\", \"id\": \"db62db1a-4a78-4634-84cc-dee63bbef3ff\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"① 退还货款 1,880 元：可以，基础请求。依据《食品安全法》第148条和买卖合同解除/退货规则。注意：退款与退货对应，商品要保留到举证、开庭结束，别提前寄回。\"}}]}}, {\"object\": \"block\", \"id\": \"0d6612db-47f4-4e3d-8b2e-c3df7cc737c4\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"② 价款十倍赔偿 18,800 元：可以，主打请求。1,880×10=18,800。奶粉 680×10=6,800，茶 1,200×10=12,000，分项相加同样是 18,800。\"}}]}}, {\"object\": \"block\", \"id\": \"ee68ee72-7bec-4339-8586-d873582aa6a4\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"③ 医疗费 320 元：可以，作为实际损失单独主张。依据第148条“赔偿损失”部分。需要发票、病历、就诊时间与饮茶时间的对应；若检验检出非法添加，因果关系更硬。\"}}]}}, {\"object\": \"block\", \"id\": \"4a86673a-9f2e-4170-84b8-4623b44e11a6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"④ 精神损害抚慰金 20,000 元：建议不写进诉状。法律上要求“严重精神损害”（《民法典》第1183条），320 元急诊很难达到；写高了还会按标的增加诉讼费，败诉部分自己承担，显得外行。\"}}]}}, {\"object\": \"block\", \"id\": \"dece4965-1c51-4a41-8224-dc41e9403731\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑤ 让优鲜购平台赔：暂时不列平台为被告。卖家主体信息明确，平台没有《消保法》第44条规定的“不能提供卖家真实信息”或“明知应知不处理”情形。先书面投诉并保留回复；只有卖家失联、店铺注销或平台拒不提供资质时，再追加平台。\"}}]}}, {\"object\": \"block\", \"id\": \"bf8a9daa-8841-4cc9-8cd5-0c85d0b020d6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⑥ “我看过差评，会不会赔不了”：这不是诉讼请求，是卖家的抗辩。食品领域“知假买假”不影响索赔（最高法食药纠纷规定第3条），你各买 1 件也属合理消费。诉状里不用主动写，庭上被提出时再反驳。\"}}]}}, {\"object\": \"block\", \"id\": \"f80b73d7-0aec-45ce-861c-0e3b01491d43\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"退一赔十到底怎么算\"}}]}}, {\"object\": \"block\", \"id\": \"20b22343-2fe7-4ee6-82db-947635cde306\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“退一”=退货款 1,880 元；“赔十”=价款十倍 18,800 元；合计 20,680 元，不是 1,880×10 再另加退款，而是 1,880×11。\"}}]}}, {\"object\": \"block\", \"id\": \"67278b77-7817-4cef-86a6-bba6e981d0d3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第148条是“价款十倍”或“损失三倍”二选一，不是同时要。你损失只有医疗 320 元，三倍=960 元，远低于价款十倍 18,800 元，所以选价款十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"3c219a90-bb95-49f1-82d2-c332a9958c70\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十倍不足 1,000 元的按 1,000 元保底；本案每项十倍都超过 1,000 元，不触发保底。\"}}]}}, {\"object\": \"block\", \"id\": \"2cde5140-d29f-4d79-8f42-34a42a95199f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不能同时要“十倍 + 三倍 + 退款 + 精神损害”四份惩罚性赔偿；惩罚性赔偿同一行为只选一种算法，否则会被法官认为重复主张。\"}}]}}, {\"object\": \"block\", \"id\": \"3aae296f-ae10-49e2-8c88-d65c5964490b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"建议的诉讼请求写法\"}}]}}, {\"object\": \"block\", \"id\": \"c2943c3e-e518-4c6f-8f3a-8fe55a2c4cb1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"判令被告退还货款 1,880 元；\"}}]}}, {\"object\": \"block\", \"id\": \"7a57f6ec-cb1f-4c6a-8967-d11b2b3f9f80\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"判令被告支付价款十倍赔偿金 18,800 元；\"}}]}}, {\"object\": \"block\", \"id\": \"22d92b11-52c6-49a7-8a12-01e736c99f0a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"判令被告赔偿医疗费 320 元、交通费 __ 元（有票据才写）；\"}}]}}, {\"object\": \"block\", \"id\": \"25016f58-26d1-4b8d-841b-e42bcfa0f94d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"判令被告承担本案检验费 __ 元、诉讼费。\"}}]}}, {\"object\": \"block\", \"id\": \"6d353abc-8591-4802-8953-68b473886276\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"合计（不含检验费、交通费）：1,880 + 18,800 + 320 = 21,000 元。诉讼费按此约 325 元，简易程序减半约 163 元，胜诉后由被告负担。\"}}]}}, {\"object\": \"block\", \"id\": \"ac0656ea-c458-4501-8a4e-7bc8bbefa563\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"⚠️\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不要写：①十倍和三倍同时要；②退款后再要“精神损失 2 万”；③没有依据就把平台列为被告；④在诉状里主动写“我看过差评”。这四项最容易让法官觉得不专业。\"}}]}}, {\"object\": \"block\", \"id\": \"168b337d-8287-4762-843f-1d943ce47ebb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"该要但别漏\"}}]}}, {\"object\": \"block\", \"id\": \"55c2c4be-601e-4945-85d1-3747df4a3cc6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"检验费：实际发生多少要多少，保留发票和委托单；诉请写“由被告承担”。\"}}]}}, {\"object\": \"block\", \"id\": \"dca6e71e-ea77-4eca-8271-14f5de379174\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"交通费：有发票/打车记录就写，没有就别编。\"}}]}}, {\"object\": \"block\", \"id\": \"19600cde-1936-48eb-8d19-3efce876cdee\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"误工费：只有能证明请假和扣工资才提，否则不提。\"}}]}}, {\"object\": \"block\", \"id\": \"d278e17a-4dbb-4d6f-8cf9-a647a9c5b271\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼费：写“由被告承担”，不写进标的额。\"}}]}}, {\"object\": \"block\", \"id\": \"eed2cd1d-92d4-404b-896f-7d8c84769f1d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"律师费：一般不支持由对方承担，除非有合同约定或法律特别规定；没有就别抱期望。\"}}]}}, {\"object\": \"block\", \"id\": \"fa153c80-cc19-4308-869d-a9092c9e311f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🧭\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一句话：这次官司就提“退款 1,880 + 十倍 18,800 + 医疗 320 + 检验费/诉讼费”，合计约 21,000 元；精神损害 2 万不写，平台暂时不告，知假买假只在被告抗辩时反驳。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

