  "result": "[{\"post_id\": \"oap_food_s4_20260524\", \"account_id\": \"oa_pudong_court\", \"title\": \"网购食品案件证据和实物保管提示\", \"summary\": \"当事人应保留订单、支付记录、商品页面、客服沟通、开箱材料和涉案食品实物；涉及食品安全专门问题的，可依法申请具备资质的机构检验。\", \"url\": \"https://court.pudong.gov.cn/notice/evidence-20260524\", \"published_at\": \"2026-05-24T09:45:00+08:00\"}, {\"post_id\": \"oap_food_s1_20260521\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷诉讼服务更新\", \"summary\": \"浦东法院汇总网购食品纠纷的管辖、起诉材料、惩罚性赔偿、平台责任、证据保全和检验申请事项，供当事人办理立案和举证时核对。\", \"url\": \"https://court.pudong.gov.cn/notice/food-20260521\", \"published_at\": \"2026-05-21T08:50:00+08:00\"}, {\"post_id\": \"oap_ct_06\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知⑥：证据与食品检验\", \"summary\": \"消费者应保留涉案食品实物(尽量未拆封原样封存)、电商订单与支付记录、商品页面截图、与客服聊天记录、开箱视频等证据。食品是否不符合安全标准涉及专门性问题，必要时应由具备食品检验资质(CMA 资质认定、必要时 CNAS 认可)的机构检验；无资质机构出具的检验报告可能不被采信。\", \"url\": \"https://court.pudong.gov.cn/notice/f06\", \"published_at\": \"2026-04-10T09:50:00Z\"}, {\"post_id\": \"oap_ct_05\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知⑤：标签瑕疵不影响安全的除外\", \"summary\": \"食品符合食品安全标准，但标签、说明书仅存在不影响食品安全且不会对消费者造成误导的瑕疵的，消费者主张价款十倍惩罚性赔偿的，人民法院不予支持(食品安全法第一百四十八条但书、最高法食药纠纷规定第十五条)。但进口食品无中文标签、超过保质期、非法添加、无合格证明等属实质不符合安全标准，不属此种\\\"瑕疵除外\\\"情形。\", \"url\": \"https://court.pudong.gov.cn/notice/f05\", \"published_at\": \"2026-04-10T09:40:00Z\"}, {\"post_id\": \"oap_ct_04\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知④：被告主体(生产者/销售者择一·平台责任)\", \"summary\": \"不符合食品安全标准食品的惩罚性赔偿，消费者可向生产者或者销售者择一主张，赔付方可向有过错方追偿。网络交易平台不能提供销售者真实名称、地址和有效联系方式的，消费者可请求平台先行承担赔偿责任；平台明知或应知销售者侵害消费者权益未采取必要措施的，与销售者承担连带责任。\", \"url\": \"https://court.pudong.gov.cn/notice/f04\", \"published_at\": \"2026-04-10T09:30:00Z\"}]"
}

