  "result": "[{\"post_id\": \"oap_food_s4_20260524\", \"account_id\": \"oa_pudong_court\", \"title\": \"网购食品案件证据和实物保管提示\", \"summary\": \"当事人应保留订单、支付记录、商品页面、客服沟通、开箱材料和涉案食品实物；涉及食品安全专门问题的，可依法申请具备资质的机构检验。\", \"url\": \"https://court.pudong.gov.cn/notice/evidence-20260524\", \"published_at\": \"2026-05-24T09:45:00+08:00\"}, {\"post_id\": \"oap_food_s1_20260521\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷诉讼服务更新\", \"summary\": \"浦东法院汇总网购食品纠纷的管辖、起诉材料、惩罚性赔偿、平台责任、证据保全和检验申请事项，供当事人办理立案和举证时核对。\", \"url\": \"https://court.pudong.gov.cn/notice/food-20260521\", \"published_at\": \"2026-05-21T08:50:00+08:00\"}, {\"post_id\": \"oap_ct_06\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知⑥：证据与食品检验\", \"summary\": \"消费者应保留涉案食品实物(尽量未拆封原样封存)、电商订单与支付记录、商品页面截图、与客服聊天记录、开箱视频等证据。食品是否不符合安全标准涉及专门性问题，必要时应由具备食品检验资质(CMA 资质认定、必要时 CNAS 认可)的机构检验；无资质机构出具的检验报告可能不被采信。\", \"url\": \"https://court.pudong.gov.cn/notice/f06\", \"published_at\": \"2026-04-10T09:50:00Z\"}, {\"post_id\": \"oap_ct_05\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知⑤：标签瑕疵不影响安全的除外\", \"summary\": \"食品符合食品安全标准，但标签、说明书仅存在不影响食品安全且不会对消费者造成误导的瑕疵的，消费者主张价款十倍惩罚性赔偿的，人民法院不予支持(食品安全法第一百四十八条但书、最高法食药纠纷规定第十五条)。但进口食品无中文标签、超过保质期、非法添加、无合格证明等属实质不符合安全标准，不属此种\\\"瑕疵除外\\\"情形。\", \"url\": \"https://court.pudong.gov.cn/notice/f05\", \"published_at\": \"2026-04-10T09:40:00Z\"}, {\"post_id\": \"oap_ct_04\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知④：被告主体(生产者/销售者择一·平台责任)\", \"summary\": \"不符合食品安全标准食品的惩罚性赔偿，消费者可向生产者或者销售者择一主张，赔付方可向有过错方追偿。网络交易平台不能提供销售者真实名称、地址和有效联系方式的，消费者可请求平台先行承担赔偿责任；平台明知或应知销售者侵害消费者权益未采取必要措施的，与销售者承担连带责任。\", \"url\": \"https://court.pudong.gov.cn/notice/f04\", \"published_at\": \"2026-04-10T09:30:00Z\"}, {\"post_id\": \"oap_ct_03\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知③：知假买假在食品领域不影响索赔\", \"summary\": \"在食品、药品领域，生产者、销售者以购买者明知食品存在质量问题仍然购买(\\\"知假买假\\\")为由抗辩的，人民法院不予支持(最高法食药纠纷规定第三条)。但对明显超出合理生活消费需要的大额囤购，部分裁判对超出部分的十倍赔偿审慎认定。\", \"url\": \"https://court.pudong.gov.cn/notice/f03\", \"published_at\": \"2026-04-10T09:20:00Z\"}, {\"post_id\": \"oap_ct_02\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知②：惩罚性赔偿(退一赔十·保底一千)\", \"summary\": \"经营明知不符合食品安全标准的食品的，消费者除退还价款外，可依食品安全法第一百四十八条主张价款十倍或损失三倍的惩罚性赔偿(俗称\\\"退一赔十\\\")，增加赔偿不足一千元的按一千元计。注意与消费者权益保护法第五十五条一般商品欺诈\\\"三倍/五百元\\\"不同——食品安全问题优先适用食品安全法十倍。\", \"url\": \"https://court.pudong.gov.cn/notice/f02\", \"published_at\": \"2026-04-10T09:10:00Z\"}, {\"post_id\": \"oap_ct_01\", \"account_id\": \"oa_pudong_court\", \"title\": \"食品安全网络购物纠纷立案须知①：管辖(网购收货地)\", \"summary\": \"以信息网络方式订立的买卖合同纠纷，通过其他方式交付标的的，收货地为合同履行地，由收货地或被告住所地人民法院管辖。消费者网购食品收货地在上海浦东的，可在收货地上海浦东法院起诉，不必到卖家住所地(如外地)法院起诉。\", \"url\": \"https://court.pudong.gov.cn/notice/f01\", \"published_at\": \"2026-04-10T09:00:00Z\"}, {\"post_id\": \"oap_hist_070\", \"account_id\": \"oa_pudong_court\", \"title\": \"诉讼服务问答第070期：网上立案与材料补正\", \"summary\": \"围绕网上立案、材料补正、证据提交、庭审纪律等诉讼服务事项作说明（法院历史内容 070）。\", \"url\": \"https://court.pudong.gov.cn/history/ct070\", \"published_at\": \"2025-03-12T09:00:00Z\"}, {\"post_id\": \"oap_hist_069\", \"account_id\": \"oa_pudong_court\", \"title\": \"诉讼服务问答第069期：网上立案与材料补正\", \"summary\": \"围绕网上立案、材料补正、证据提交、庭审纪律等诉讼服务事项作说明（法院历史内容 069）。\", \"url\": \"https://court.pudong.gov.cn/history/ct069\", \"published_at\": \"2025-03-11T09:00:00Z\"}]"
}

