"block\", \"id\": \"77449812-ff36-4abd-8fdf-2c4d4866d682\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"原告身份证复印件（正反面）1-3 份，签名。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"9acbedf1-d24c-4d52-840d-60729a64b5eb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"被告工商登记信息：国家企业信用信息公示系统打印件（含法定代表人、统一社会信用代码、住所地）。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"a20f56b0-8d40-4ba8-8382-8becc3c8d7f7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"送达地址确认书：网上立案系统一般会生成，按提示填写并签名。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"0e2d6f60-8d85-4c69-88dc-33a1c4f2415a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼费：立案审核通过后按通知预交；保留凭证。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"fa325c63-9eca-454f-85f6-3f76c