d\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、诉讼费怎么算、要不要预交\"}}]}}, {\"object\": \"block\", \"id\": \"30dd5146-e18f-436a-8368-67d57f66195c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"标的约 21,000 元（退款 1,880 + 十倍 18,800 + 医疗 320）：受理费 = 50 + (21,000-10,000)×2.5% = 325 元。\"}}]}}, {\"object\": \"block\", \"id\": \"853e9b5c-0c07-4c24-8622-8e3672ada298\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"适用简易程序减半交纳：约 162.5 元。\"}}]}}, {\"object\": \"block\", \"id\": \"5921d171-eb90-415e-85dc-5662681b9737\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"要预交：立案审核通过后，法院通知交费，原告先垫付；胜诉后由被告负担，判决书写明。\"}}]}}, {\"object\": \"block\", \"id\": \"cebcd373-02fc-486b-8d34-4f2a4ac4abc6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"经济困难可申请缓交/减交/免交，需提交证明材料；不影响先立案。\"}}]}}, {\"object\": \"block\", \"id\": \"b85ba910-8a5e-43b4-8947-557c8eaf2cf5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果诉请加上检验费，标的额会增加，诉讼费按增加后的金额重算；不要把精神损害 2 万写进去，否则诉讼费会明显变高。\"}}]}}, {\"object\": \"block\", \"id\": \"c2f7c0ef-18f6-4d9c-8d96-e29bfb95f1a5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、食品检验怎么申请\"}}]}}, {\"object\": \"block\", \"id\": \"53b6d97a-3099-4fc4-8b80-777db1409a4a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"两条路，建议先走第一条：\"}}]}}, {\"object\": \"block\", \"id\": \"cdd45b71-2958-4f83-844b-a102b15c5204\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"① 诉前自行委托 JY-006 沪正检测（推荐）：做“标签符合性 + 非法添加筛查”，拿报告作为证据提交。报告要盖 CMA 章、附 CNAS 认可标识和资质附表、收样单、发票；报告要写清样品来源和封样情况。\"}}]}}, {\"object\": \"block\", \"id\": \"b60cd01f-200a-46d1-833a-e7217047a821\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"② 诉讼中申请法院委托检验：在举证期限届满前提交书面申请，写明待证事实（茶是否含非法添加、标签是否符合标准）、检验事项、拟选机构；法院组织质证后委托，费用先由申请方垫付，最终按责任分担。\"}}]}}, {\"object\": \"block\", \"id\": \"8be15a4c-a2ed-450c-8afe-9e3f16fa396c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"对方对报告有异议：申请检验人出庭说明，或申请法院委托复检；如果卖家/平台持有奶粉入境检验检疫证明，可申请法院调查取证或责令提交。\"}}]}}, {\"object\": \"block\", \"id\": \"92988eca-31d8-4908-8a34-36ce66011162\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"999e9ebe-39e2-49f5-8098-cb5d1a0ed394\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🔬\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"关键：检验报告不是“有了就一定赢”，但资质齐全、程序规范、样品来源清楚，法院采信概率高；无资质或结果挂钩的报告，反而会被对方抓住。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

