  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"85848ca7-1468-4919-8f1a-882c5293b8b5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三、待你决定：平台要不要一起告\"}}]}}, {\"object\": \"block\", \"id\": \"ad1cd064-6744-446c-80a3-d4590ff48a3c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三个方案，利弊如下，最终你选：\"}}]}}, {\"object\": \"block\", \"id\": \"a4435cb9-8381-4357-898b-e6c5ffdbccd5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案 A：只告卖家（当前草稿）。简单、快、管辖清楚；风险是卖家关店/失联后执行难。\"}}]}}, {\"object\": \"block\", \"id\": \"eb6f3010-9993-4715-80ec-f4fe365fc895\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案 B：卖家 + 优鲜购平台共同被告。理由写“平台收到投诉后未提供卖家有效联系方式/未采取必要措施”；优点是平台在上海、偿付能力强、施压明显；风险是若平台能提供卖家信息且已处理，对平台之诉可能被驳回，案件变复杂。\"}}]}}, {\"object\": \"block\", \"id\": \"7f1d80ba-e06a-4173-851d-df056faf93bd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案 C：先告卖家，保留追加平台。立案后如确认卖家失联、店铺注销、平台拒不提供信息，再申请追加平台；前提是现在就发平台书面投诉并保留回复。\"}}]}}, {\"object\": \"block\", \"id\": \"8e49e704-98c2-4e43-8fd6-259e1f743bc9\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🧭\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"我的建议（仅供参考，最终你定）：先做平台书面投诉 + 截图店铺状态。如果确认店铺关闭/客服失联/平台不提供卖家有效信息，选 B 或 C；如果平台能提供信息且店铺仍在经营，选 A。不要在没有证据的情况下直接把平台写成连带被告。\"}}]}}, {\"object\": \"block\", \"id\": \"75443c81-9c4c-4244-8a9c-e55154ee56a6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、卖家跑路找谁赔\"}}]}}, {\"object\": \"block\", \"id\": \"b72c67d1-2b2c-497b-8519-0698e3349e8c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第一顺位仍是卖家：杭州环球优选食品有限公司。公司即使关店，只要没注销，仍可作为被告；判决后可执行公司财产。\"}}]}}, {\"object\": \"block\", \"id\": \"56bb88a2-0e39-4d94-83f4-71aab698827e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第二顺位是平台：依《消保法》第44条，平台不能提供卖家真实名称、地址和有效联系方式的，可要求平台先行赔偿；平台明知/应知侵权不采取必要措施的，承担连带责任。\"}}]}}, {\"object\": \"block\", \"id\": \"6bc02517-f915-4e9d-8657-de1698901ed0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第三顺位是生产者/进口商：如果能通过奶粉外包装、报关信息或平台披露找到境内进口商/生产者，也可依《食品安全法》第148条向其主张；目前信息不足。\"}}]}}, {\"object\": \"block\", \"id\": \"b397dcdb-61f8-4c23-8e7d-9f82eee4465f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果公司注销时未依法清算，可进一步追究股东责任；这一步较复杂，真走到那一步再找律师。\"}}]}}, {\"object\": \"block\", \"id\": \"ec948b26-ff40-4f57-8e4b-6cb5430ff455\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"现在立刻做的四件事\"}}]}}, {\"object\": \"block\", \"id\": \"f60de3e4-dd54-4803-8720-a5e0955d5984\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"截图店铺页面、关店/停业公告、客服失联提示；记录时间。尝试客服时录屏或截图，保存“发送失败/无人回复”。\"}}]}}, {\"object\": \"block\", \"id\": \"ef27c71d-9790-485d-8681-cec11fb905aa\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"向优鲜购发书面投诉：要求提供卖家真实名称、地址、有效联系方式、营业执照、食品经营许可证、奶粉入境检验检疫证明，并要求平台对卖家采取必要措施。保留平台回复。\"}}]}}, {\"object\": \"block\", \"id\": \"bee64d9f-8c21-4148-8025-7d7bb323b7d1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"在国家企业信用信息公示系统查卖家状态：存续/经营异常/注销/吊销，打印带日期。\"}}]}}, {\"object\": \"block\", \"id\": \"468d90d1-be41-42c6-8625-c1aeea9feabd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果确认店铺关闭/客服失联，再决定是否把平台列为共同被告；不要拖到卖家注销后才动。\"}}]}}, {\"object\": \"block\", \"id\": \"a2ffcd59-3bdc-465f-8c7b-532add7a9fc3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"平台投诉可用的话术\"}}]}}, {\"object\": \"block\", \"id\": \"72103231-2dc8-4f80-8989-02d7bb94c503\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"致优鲜购平台：本人赵萌，订单号 YX20260418，在“环球优选”店铺购买进口奶粉和养生茶共 1,880 元。现该店铺疑似关闭、客服失联。请提供卖家真实名称、地址、有效联系方式、营业执照、食品经营许可证及奶粉入境检验检疫证明，并对卖家采取必要措施。否则本人将依《消保法》第44条追究平台责任。\"}}]}}, {\"object\": \"block\", \"id\": \"be213746-9966-4017-8f96-29e40a887f86\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、递交前最后确认清单\"}}]}}, {\"object\": \"block\", \"id\": \"d1af09c2-8d06-4cf3-81be-68ac636c98f3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"起诉状定稿、打印、签名（本页草稿待你改）。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"5e678c1b-4f1e-4e71-8c4e-e08ef898b789\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"被告最终确定：只告卖家，还是卖家+平台（方案 A/B/C）。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"7a35b540-da97-4b64-84b5-620f955980ad\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼请求金额最终确认：1,880 + 18,800 + 320 + 检验费/交通费。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"5c45153d-e048-47e2-8b1f-e22dbd5ba8c7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据 E1-E11 打印、编号、装订；E12 检验报告待补；E13 平台投诉记录待补。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"53c254d5-3ad6-4112-82b1-829d4710e2ba\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"被告工商登记打印件、订单详情页、完整聊天记录、身份证复印件、送达地址确认书。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"f9439b79-0664-4c9d-87aa-3278eaee58fc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼费约 325 元（简易减半约 163 元），按通知预交。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"171d33b7-f49c-44e1-8883-500c5aee1079\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"检验方式决定：诉前委托 JY-006，或立案后申请法院委托。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"8c18377b-a6dc-4f30-8a73-ed21348d0c64\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"平台书面投诉已发、回复已保存；店铺状态已截图。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"27c1a20f-d192-44ea-868c-87ed6f092f57\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a197b633-8994-45d6-8c59-d5dfb1d7541d\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_tra