d\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"把邮件 #1198 保存为 E14：打印完整邮件（含发件人、时间、Message-ID），截图工单页面。\"}}]}}, {\"object\": \"block\", \"id\": \"103aced6-23b2-45bd-88c6-fef0ef46cd00\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a189b128-25c1-4ef6-8375-6aa071ebd3a5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"向优鲜购发书面催告（用下面话术），限 3 个工作日书面回复；保留发送记录和回复。\"}}]}}, {\"object\": \"block\", \"id\": \"a85e5ef9-4beb-4f82-8480-276e5edf87c6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a189b128-25c1-4ef6-8375-6aa071ebd3a5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"查国家企业信用信息公示系统：卖家是存续、经营异常、注销还是吊销；打印带日期。\"}}]}}, {\"object\": \"block\", \"id\": \"e615a156-0274-41d0-8f8c-888b8be357a9\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a189b128-25c1-4ef6-8375-6aa071ebd3a5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"在 A/B/C 中选一个；选 B 就把平台加进起诉状，选 C 就先按卖家版本立案并保留追加。\"}}]}}, {\"object\": \"block\", \"id\": \"af8c4192-dfc2-43bc-8444-4859a4bf95ae\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a189b128-25c1-4ef6-8375-6aa071ebd3a5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"