ildren\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🟡\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"这四个决定都由你做。你选完，我按你选的版本把起诉状和平台催告改好；正式提交和签名仍由你本人完成。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
