  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"fe686ba3-c1fe-4369-8820-a6f266be49c7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、举证责任与要求对方提交的材料\"}}]}}, {\"object\": \"block\", \"id\": \"cbb67d37-95c1-4ce4-8067-66dc7daaf670\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"原告已举证：订单、支付、收货、开箱视频、奶粉实物无中文标签、茶页面功效宣传、就医发票病历。购买和标签问题的事实证据在原告手里。\"}}]}}, {\"object\": \"block\", \"id\": \"8484c24a-4ad9-45b4-800b-a37e3bbea535\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"被告若主张“食品符合安全标准”“标签只是小瑕疵”，应由被告举证：同批次检验报告、入境货物检验检疫证明、中文标签样张、进货查验记录。不能只凭口头陈述。\"}}]}}, {\"object\": \"block\", \"id\": \"9bef446b-01b2-47fd-85eb-6ee25f6b9d7e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"建议当庭/书面向法院提出：责令被告提交上述材料；若被告拿不出入境检验检疫证明、中文标签样张或同批次报告，应承担举证不能的后果。\"}}]}}, {\"object\": \"block\", \"id\": \"179097be-54a7-4e79-8c***\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果被告提交检验报告：核对是否同一批次、是否 CMA/CNAS 资质、检测项目是否覆盖标签符合性和非法添加、报告是否完整；不满足的，不认可其证明目的。\"}}]}}, {\"object\": \"block\", \"id\": \"d615c94e-0f23-4d15-8623-d619a9f34136\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、法庭陈述版（可直接念）\"}}]}}, {\"object\": \"block\", \"id\": \"dd9f15e3-56c3-4a38-8e63-135df0101ff2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"审判长，关于被告第一点“最多退一赔三”：本案是食品安全纠纷，应适用《食品安全法》第148条，而不是《消法》第55条。被告把普通消费欺诈的三倍拿来限制食品安全十倍，是混淆法律依据。十倍是法定标准，不存在“最多三倍”的上限。\"}}]}}, {\"object\": \"block\", \"id\": \"e8cbc800-42ac-4485-8662-02943bdaf00c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"关于第二点“知假买假”：食品领域这个抗辩不成立。最高法食药纠纷规定第3条明确不支持，上海一中院(2025)沪01民终05600号也是这个结论。我各买 1 件，是合理生活消费，不是囤货索赔；看过评论也不等于知道食品不符合安全标准。\"}}]}}, {\"object\": \"block\", \"id\": \"b99aeb0b-13cd-4d96-8324-b0ade5dad466\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"关于第三点“只是标签小瑕疵”：这不是字号、标点问题，而是整罐没有中文标签、没有中文说明书。食品安全法第97条要求进口预包装食品必须有中文标签，没有的不得进口、不得销售；消费者无法知悉成分、保质期和境内代理商，属于实质性不符合食品安全标准，不适用第148条但书。判例(2025)沪0112民初18900号、(2025)沪0115民初20100号都支持十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"794c422e-ed5f-46cf-87ae-b490f0e1dd82\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、判例索引\"}}]}}, {\"object\": \"block\", \"id\": \"d6836569-46a8-4b70-8b11-de6f667813fc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0112民初18900号：进口食品整罐无中文标签，判十倍。直接对应奶粉。\"}}]}}, {\"object\": \"block\", \"id\": \"fab31653-db1e-453c-8d04-cbdbc93cb153\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0115民初20100号：进口食品无入境检验检疫证明，判十倍。对应被告拿不出合格证明。\"}}]}}, {\"object\": \"block\", \"id\": \"24c5ba85-3e38-48ff-8990-5889821e7f1e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0112民初15800号：普通食品无保健食品批号却宣称治疗高血压、降糖，判十倍。对应茶的功效宣传。\"}}]}}, {\"object\": \"block\", \"id\": \"836d37a6-23fe-44a5-8dc3-d359a8b43c17\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0115民初20300号：代用茶检出西布曲明等非法添加物，判十倍。对应茶的检验报告。\"}}]}}, {\"object\": \"block\", \"id\": \"18b48eff-1e27-42ff-8026-66da87c14f16\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪01民终05600号：食品领域“知假买假”不影响十倍索赔。直接反驳第二点。\"}}]}}, {\"object\": \"block\", \"id\": \"f24b471e-12c7-427a-8bbf-91129f479b16\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0115民初20600号：明确区分普通商品欺诈三倍与食品安全十倍，本案适用十倍。直接反驳第一点。\"}}]}}, {\"object\": \"block\", \"id\": \"c0287767-43de-4810-8300-78fb94db0cec\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2025)沪0112民初16800号：仅字号偏小、标点错误等不影响安全且不误导的瑕疵，才不支持十倍。用来反衬本案“整罐无中文标签”。\"}}]}}, {\"object\": \"block\", \"id\": \"c04c4210-a08d-47d0-8301-aebbd7dd236a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"(2024)浙0110民初18700号：明显超出合理生活消费的大额囤购，超出部分十倍赔偿审慎认定。你各买 1 件，不适用。\"}}]}}, {\"object\": \"block\", \"id\": \"75b63281-0d33-442c-808c-fa3dcf0d7093\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d4d44ee9b7\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"七、待补/待确认\"}}]}}, {\"object\": \"block\", \"id\": \"5909e259-d4a1-4938-8a06-ad98452db27a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"3add425e-7956-4ce1-81ec-42d