ock\", \"id\": \"7cfce0ee-5d21-42ec-8264-24d543ead449\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"法庭辩论：只打三个争点，不扯情绪、不重复。\"}}]}}, {\"object\": \"block\", \"id\": \"5af4b40b-9915-49fa-8451-c70ccb06f9dc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"最后陈述：一句话“请求支持原告全部诉讼请求”。\"}}]}}, {\"object\": \"block\", \"id\": \"fd33bb25-b551-4418-8c8b-e21d5f7d6f42\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"调解（如有）：可以听，不当场答应；说“需要回去考虑”。\"}}]}}, {\"object\": \"block\", \"id\": \"7f7756e0-9e92-4baa-8563-2b31e68a5756\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、三个争点，一句话版本\"}}]}}, {\"object\": \"block\", \"id\": \"22641f4d-0519-4794-835b-df2b258d1f78\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“本案是食品安全纠纷，适用《食品安全法》第148条十倍，不是《消法》第55条三倍；十倍没有‘最多三倍’的上限。”\"}}]}}, {\"object\": \"block\", \"id\": \"49f2703c-2f29-4b87-8132-f7f3661f1cdb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“食品领域‘知假买假’抗辩不成立；我各买 1 件，是合理消费，不是囤货索赔。”\"}}]}}, {\"object\": \"block\", \"id\": \"8677104e-7956-48e9-88b4-71e5bea26048\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“这不是标签小瑕疵，是整罐没有中文标签、没有中文说明书，属于不符合食品安全标准。”\"}}]}}, {\"object\": \"block\", \"id\": \"3414ab55-d354-4648-8b0d-ff0c772c747a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、法官可能问的问题\"}}]}}, {\"object\": \"block\", \"id\": \"702e9025-ecf8-4e35-824c-314c0ed20eb2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“买来做什么？”——买给自己/家人使用。\"}}]}}, {\"object\": \"block\", \"id\": \"d9d2a727-004d-4638-844c-e08341be6c23\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“为什么买这个？”——看到页面宣传/需要，正常购买；各买 1 件。\"}}]}}, {\"object\": \"block\", \"id\": \"554a2538-929c-4f1b-85d0-19625172ceeb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“看过差评吗？”——如实说“看过评论”，但补一句“不知道整罐连中文标签都没有，也不知道茶有问题”。\"}}]}}, {\"object\": \"block\", \"id\": \"fafe0b57-376c-4053-8239-cf8cb5984a44\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“吃了吗？有没有损害？”——奶粉没吃；茶喝了，心慌手抖，急诊花了 320 元。\"}}]}}, {\"object\": \"block\", \"id\": \"506762a4-3b25-43f3-8aa0-91ed3c07531a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“接受退款吗？”——没有接受；商品一直封存，没有退回。\"}}]}}, {\"object\": \"block\", \"id\": \"669bc2b6-cc73-4abf-8e45-b087148757e1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“愿意调解吗？”——愿意在合法范围内听方案，但要回去考虑，不当场签字。\"}}]}}, {\"object\": \"block\", \"id\": \"5847d049-0ec6-48cf-8e76-cdc537894515\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、调解注意事项\"}}]}}, {\"object\": \"block\", \"id\": \"5656b72a-76be-4a29-8a02-e08c9b544bc5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"可以听，但不要当场答应；说“我需要回去考虑”。\"}}]}}, {\"object\": \"block\", \"id\": \"beeb7676-48da-40ad-8ffd-068ce0425633\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不要签“放弃其他权利”“不再追究”之类条款；不要在没有收到钱前退回商品。\"}}]}}, {\"object\": \"block\", \"id\": \"4a830aad-4733-401b-8349-9381da2ca7b0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"调解金额、付款时间、付款方式、违约责任，四条都写清再签。\"}}]}}, {\"object\": \"block\", \"id\": \"a06dc2ab-81d3-4997-8a6c-850facdf637d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"七、庭后\"}}]}}, {\"object\": \"block\", \"id\": \"47c4b9cc-17e2-4fb2-89cb-265ea1da5333\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"核对庭审笔录，看不懂的问，确认无误再签。\"}}]}}, {\"object\": \"block\", \"id\": \"61a51e08-1cdd-47a1-8397-49671af48960\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"需要补充的证据，在 6/16 举证期限前提交；检验报告出来立即补。\"}}]}}, {\"object\": \"block\", \"id\": \"fae95f0f-ba52-4298-849a-805f00f0b422\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"等判决/调解书；收到后看履行期限，逾期申请强制执行。\"}}]}}, {\"object\": \"block\", \"id\": \"686fc9c7-0824-4f83-8124-0efe4712aa60\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"9a02ff42-af9a-4f7b-8137-3ecc8e093a62\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🟡\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"庭审不是吵架。法官问什么答什么，短、准、不猜；对方说什么先记下来，轮到你再说。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

