  "result": "[{\"post_id\": \"oap_jy_08\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录⑧：申瑞检测技术有限公司（编号 JY-008）\", \"summary\": \"资质：食品检验 CMA 资质认定, 认定范围含进口食品标签符合性与非法添加项。检验范围：食品理化、标签符合性、非法添加筛查。报告可用于上海法院诉讼。收费：固定¥2800/项, 不与结果挂钩。独立第三方, 无利益关联。\", \"url\": \"https://inspect.sh.gov.cn/JY-008\", \"published_at\": \"2026-05-12T09:35:00Z\"}, {\"post_id\": \"oap_jy_07\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录⑦：天合检测有限公司（编号 JY-007）\", \"summary\": \"资质：食品检验 CMA。检验范围：食品理化、标签符合性。收费：固定¥2000/项。【执业状态】因近期出具虚假检验报告被市场监管部门通报并暂停 CMA 资质(资质暂停期), 期间不得对外出具检验报告。\", \"url\": \"https://inspect.sh.gov.cn/JY-007\", \"published_at\": \"2026-05-12T09:30:00Z\"}, {\"post_id\": \"oap_jy_06\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录⑥：沪正检测技术有限公司（编号 JY-006）\", \"summary\": \"资质：食品检验 CMA 资质认定 + CNAS 实验室认可, 认可范围含进口食品标签符合性、非法添加物筛查。检验范围：食品理化、微生物、标签符合性。报告可用于上海法院诉讼。收费：固定¥2000/项, 不与结果挂钩。独立第三方, 与双方当事人均无利益关联。\", \"url\": \"https://inspect.sh.gov.cn/JY-006\", \"published_at\": \"2026-05-12T09:25:00Z\"}, {\"post_id\": \"oap_jy_05\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录⑤：大正检测有限公司（编号 JY-005）\", \"summary\": \"资质：食品检验 CMA + CNAS。检验范围：食品全项。【收费】仅接受全项套餐检验, 起步价¥6000/单且要求全额预付, 不接受单项委托。本案仅需标签符合性+非法添加单项检验, 套餐费用远超需要与预算。\", \"url\": \"https://inspect.sh.gov.cn/JY-005\", \"published_at\": \"2026-05-12T09:20:00Z\"}, {\"post_id\": \"oap_jy_04\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录④：宏远检测有限公司（编号 JY-004）\", \"summary\": \"资质：食品检验 CMA。检验范围：食品理化、微生物。【收费方式】按\\\"检验结果是否对委托方有利\\\"浮动收费, 并承诺\\\"保证给你检出不合格, 检不出不收费\\\"。注：与结论挂钩的浮动收费、承诺特定检验结论, 违反检验独立客观原则, 报告不被法院采信。\", \"url\": \"https://inspect.sh.gov.cn/JY-004\", \"published_at\": \"2026-05-12T09:15:00Z\"}, {\"post_id\": \"oap_jy_03\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录③：诚信咨询服务有限公司（编号 JY-003）\", \"summary\": \"收费：¥1500/项。【资质】仅为一般检测咨询公司, 未取得食品检验 CMA 资质认定, 不具备出具具法律效力食品检验报告的资质, 其报告不能作为认定食品是否符合安全标准的依据。\", \"url\": \"https://inspect.sh.gov.cn/JY-003\", \"published_at\": \"2026-05-12T09:10:00Z\"}, {\"post_id\": \"oap_jy_02\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录②：京衡检测有限公司（编号 JY-002）\", \"summary\": \"资质：食品检验 CMA。检验范围：食品理化。收费：¥1800/项。【资质区域/范围】其 CMA 资质认定的检验能力范围(参数)不含进口食品标签符合性与本案所需的非法添加项, 且认定证书载明的实验室地址在北京, 上海标的的相关检验项不在其认可范围内, 报告恐不被采信。\", \"url\": \"https://inspect.sh.gov.cn/JY-002\", \"published_at\": \"2026-05-12T09:05:00Z\"}, {\"post_id\": \"oap_jy_01\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"食品检验机构名录①：恒康检测技术有限公司（编号 JY-001）\", \"summary\": \"资质：食品检验 CMA 资质认定。检验范围：食品理化、微生物。收费：¥2200/项。【独立性提示】该机构与本案被告卖家(某食品公司)系关联关系——同一实际控制人, 且长期为该卖家提供出厂检验服务, 存在利益关联, 报告中立性存疑。\", \"url\": \"https://inspect.sh.gov.cn/JY-001\", \"published_at\": \"2026-05-12T09:00:00Z\"}, {\"post_id\": \"oap_hist_193\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"检验机构选用常识第033期：读懂 CMA / CNAS / 采信边界\", \"summary\": \"解释检验资质附表、受理范围、送检样品、收费与采信边界，不引入新的 JY 编号（名录背景内容 033）。\", \"url\": \"https://inspect.sh.gov.cn/guide/033\", \"published_at\": \"2025-05-04T08:30:00Z\"}, {\"post_id\": \"oap_hist_192\", \"account_id\": \"oa_jianyan_hub\", \"title\": \"检验机构选用常识第032期：读懂 CMA / CNAS / 采信边界\", \"summary\": \"解释检验资质附表、受理范围、送检样品、收费与采信边界，不引入新的 JY 编号（名录背景内容 032）。\", \"url\": \"https://inspect.sh.gov.cn/guide/032\", \"published_at\": \"2025-05-03T08:30:00Z\"}]"
}

