block\", \"id\": \"898aadb1-d418-49ed-87d0-b887be6c6d1c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"涉案食品实物：奶粉、茶，原样封存，装袋带庭。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"15dc9435-adb8-4e2a-8439-7f77c3e494f3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"检验材料：JY-006 暂停通知（邮件 #1202）、JY-006 委托/付款/收样记录、JY-008 委托或收样单（如已办）。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"fec03914-3f0d-4063-819c-681a7a968e54\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"书面《检验申请》+《延长举证期限申请》（如报告来不及）；庭上提交，说明是机构资质暂停导致。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"41f10649-fb26-4d44-868b-4f74ed9fe5b7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"to_do\", \"to_do\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"手机满电 + 充电宝 + 视频备份 U 盘；提前试播。\"}}], \"checked\": false}}, {\"object\": \"block\", \"id\": \"35c3a298-6583-43f7-8759-76034f1fad94\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"📌\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据目录里 E12 的状态写“原 JY-006 因 CMA 暂停未出报告，已转 JY-008/申请法院委托”，不要写成“已有报告”。\"}}]}}, {\"object\": \"block\", \"id\": \"da1f39cd-a244-4ad8-88a9-16af8f2181f4\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、庭上怎么说\"}}]}}, {\"object\": \"block\", \"id\": \"4f3a5202-5e3a-4c30-8176-bb16e18d86d7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“审判长，原定 JY-006 沪正检测因食品检验 CMA 资质暂停，尚未出具报告，这是机构原因，不是原告拖延。原告已在 6 月 10 日联系 JY-008 申瑞检测并安排送检/转样，恳请法庭准许在举证期限内补充提交报告；如时间来不及，恳请法院委托检验或准许延期举证。”\"}}]}}, {\"object\": \"block\", \"id\": \"4a1dfcce-7c19-4ab6-8a8a-d6a477681274\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“即使茶的检验报告尚未提交，商品页面宣称‘专治高血压、降血糖、根治失眠’已经足以证明普通食品违法宣称疾病治疗功效，依据《食品安全法》第148条和判例 f13，仍应支持十倍。”\"}}]}}, {\"object\": \"block\", \"id\": \"f5275967-5886-4142-8e71-f14b8becaee7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"quote\", \"quote\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"“奶粉部分不依赖检验报告：整罐没有中文标签、没有中文说明书，实物、照片、开箱视频和市监局公告已经证明，依据第97条、第148条和判例 f02/f18，应支持十倍。”\"}}]}}, {\"object\": \"block\", \"id\": \"8cb1d5cb-0a8f-48d2-8083-87ea24ea4c26\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、今天必须完成\"}}]}}, {\"object\": \"block\", \"id\": \"2f11f857-0c0b-4b83-8a07-b4e48a478eab\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"联系 JY-006，确认样品位置/是否拆封，要求书面确认并退回或转交。\"}}]}}, {\"object\": \"block\", \"id\": \"6ea03db8-62f2-446f-863d-37b7c20c22f1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"5fc54909-3a71-4804-8dbb-a30f6b632186\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"c