  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"87532b91-ee15-40a9-8708-f982baf11e1e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼请求：退款 1,880 元 + 价款十倍 18,800 元 + 医疗费 320 元 + 检验费/诉讼费。\"}}]}}, {\"object\": \"block\", \"id\": \"18003f68-a6a9-40a2-8b01-6ff3073259e0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第97条：进口预包装食品必须有中文标签、中文说明书，载明原产地和境内代理商；没有的不得进口、不得销售。\"}}]}}, {\"object\": \"block\", \"id\": \"e668116f-87b7-4cf7-8273-74bb3f21457e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第34条：禁止生产经营无标签的预包装食品、添加食品添加剂以外化学物质或其他可能危害人体健康物质的食品。\"}}]}}, {\"object\": \"block\", \"id\": \"4e2894cf-74d0-41b0-853c-458daab3194b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《食品安全法》第148条：经营明知不符合食品安全标准的食品，退款 + 价款十倍或损失三倍，择高；不足 1,000 元按 1,000 元；标签瑕疵但书仅限不影响安全且不误导。\"}}]}}, {\"object\": \"block\", \"id\": \"67c45158-32f2-466e-8a51-493d64955e5b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《消保法》第44条：平台不能提供卖家真实名称、地址、有效联系方式的，可要求平台先行赔偿；明知/应知未采取必要措施的，承担连带责任。\"}}]}}, {\"object\": \"block\", \"id\": \"1a08e7e6-3e3e-4df5-8aa4-df9d81104a2b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"最高法食药纠纷规定第3条：食品、药品领域，销售者以购买者“知假买假”抗辩的，法院不予支持。\"}}]}}, {\"object\": \"block\", \"id\": \"cb6ddac0-db77-4b61-87df-f214147977d7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"判例：f02（无中文标签十倍）、f18（无入境检验检疫证明十倍）、f13（普通食品宣称疗效十倍）、f06（代用茶非法添加十倍）、f04（知假买假不成立）、f12（区分三倍与十倍）。\"}}]}}, {\"object\": \"block\", \"id\": \"6ee4b042-2f14-42e7-86fe-fe094a9aa7aa\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据：E1-E14；奶粉实物、开箱视频、页面截图、医疗票据、平台工单；检验报告待 JY-008/法院委托。\"}}]}}, {\"object\": \"block\", \"id\": \"3044d38e-831a-4183-8857-074580d0bfa3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、对方抗辩与我方回应\"}}]}}, {\"object\": \"block\", \"id\": \"7f60cb5a-5d8d-4b1d-8495-0fc5169ac54d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩一：最多退一赔三，不是十倍\"}}]}}, {\"object\": \"block\", \"id\": \"5e240346-1585-431f-8722-5b2d44f2f1ba\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：法律适用错误。本案是食品安全纠纷，应适用《食品安全法》第148条，不是《消法》第55条；三倍是普通消费欺诈的规则，不能限制食品安全十倍。判例 f12 明确区分，f02/f13/f06 均判十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"78600618-d02f-4d02-8fff-f2db9dedc1c2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩二：原告看过差评，是知假买假/职业打假\"}}]}}, {\"object\": \"block\", \"id\": \"6025870c-0baa-4197-8583-d47bdc5d8d35\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：食品领域该抗辩不成立（食药纠纷规定第3条；f04）。原告各买 1 件，属合理生活消费，不是大额囤购（f17 不适用）。看过评论不等于知道食品不符合安全标准；职业打假的举证责任在被告。\"}}]}}, {\"object\": \"block\", \"id\": \"22a3949e-653c-4eab-84f6-c25ac53909c3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩三：无中文标签只是不影响安全的小瑕疵\"}}]}}, {\"object\": \"block\", \"id\": \"b8b2f6e7-d217-49f9-8120-1c2b16d04e51\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：整罐没有中文标签、没有中文说明书，不是字号、标点等轻微瑕疵；消费者无法知悉成分、保质期、境内代理商，属于实质性不符合食品安全标准。f02/f18 支持十倍；f07 只是反衬；浦东法院须知⑤也明确无中文标签不属瑕疵除外。\"}}]}}, {\"object\": \"block\", \"id\": \"46f7c67a-bcf2-4166-8b9c-22f6ce1ccb2a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩四：商品安全、茶没有非法添加\"}}]}}, {\"object\": \"block\", \"id\": \"33c6dd89-7ee1-4421-8eb0-e7fa9bc0ed50\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：被告主张安全，应举证同批次检验报告、入境检验检疫证明、中文标签样张、进货查验记录；拿不出承担举证不能后果。茶即使未检出非法添加，页面宣称治疗高血压、降糖仍构成违法功效宣传，f13 支持十倍。检验报告用于补强非法添加和因果关系。\"}}]}}, {\"object\": \"block\", \"id\": \"4cf84bad-0360-4cc7-8b24-5642f2f87f84\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩五：平台只是平台，不应担责\"}}]}}, {\"object\": \"block\", \"id\": \"e4a5f06b-bcb8-499d-8387-b15ac158fbbc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：平台书面确认店铺暂停营业、客服和登记电话无法接通（E14），若不能提供卖家真实名称、地址、有效联系方式，或收到通知后未采取必要措施，依《消保法》第44条应先行赔偿/连带。若平台能证明已提供有效信息并处理，平台责任可能不成立，但不影响卖家责任。\"}}]}}, {\"object\": \"block\", \"id\": \"fe46f8d5-4b04-4713-8fb1-13ef98476c78\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_3\", \"heading_3\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"抗辩六：医疗费与饮茶无关\"}}]}}, {\"object\": \"block\", \"id\": \"82a5009c-e600-4832-8e57-53012af17e65\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"回应：饮茶、症状、急诊时间连续；病历记载心慌、手抖，医生怀疑刺激性成分；320 元金额小，法院可结合日常经验判断。若检出非法添加，因果关系更硬。\"}}]}}, {\"object\": \"block\", \"id\": \"8bab3d74-7506-4b90-887e-c9473de5bf2d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、庭审后待办与风险\"}}]}}, {\"object\": \"block\", \"id\": \"91ed112d-0638-4f03-80fd-61b8f8cc4a45\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"6/16 举证节点：JY-008 报告/法院委托材料能补就补；不能补就书面说明 JY-006 资质暂停并申请延期。\"}}]}}, {\"object\": \"block\", \"id\": \"d9849b48-a24f-4cd1-86f0-444d05f15c57\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"平台责任有不确定性：取决于平台能否证明已提供有效卖家信息并采取必要措施；卖家责任不受影响。\"}}]}}, {\"object\": \"block\", \"id\": \"305276a7-84e8-4a76-89b3-1b468b61eb69\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"茶的部分有两条腿：非法添加检验（待报告）+ 普通食品宣称疗效（f13）；即使报告未出，仍可主张十倍。\"}}]}}, {\"object\": \"block\", \"id\": \"3e5a160d-fa3e-45e6-800c-ad38a52c32c9\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"收到判决后：看主文和履行期限；不服在送达后 15 日内上诉；胜诉不履行在生效后 2 年内申请执行。\"}}]}}, {\"object\": \"block\", \"id\": \"498b80e8-a538-4f86-834c-60ad70563029\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"商品继续封存，证据原件保留到案件彻底结束（含上诉/执行）。\"}}]}}, {\"object\": \"block\", \"id\": \"674d5eb3-3b8b-416a-8960-ea4fbaa7a729\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、可能的裁判走向（仅作预案，不预测结果）\"}}]}}, {\"object\": \"block\", \"id\": \"09812b09-9d96-4b10-854d-450253695cbd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"全部支持：退款 1,880 + 十倍 18,800 + 医疗 320 + 检验费/诉讼费。\"}}]}}, {\"object\": \"block\", \"id\": \"67da5bb6-8193-4f0a-81df-912c20c6ce1a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"部分支持（茶只认定宣传欺诈、不认定不安全）：奶粉十倍 6,800 + 茶三倍 3,600 + 退款 1,880 + 医疗 320 = 12,600（另加诉讼费）。\"}}]}}, {\"object\": \"block\", \"id\": \"ab82c85b-10cb-4458-80f2-00a6c3e9cb5f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不利走向：若法院认为标签问题轻微、茶不构成不安全，可能驳回部分请求；收到判决后针对理由决定是否上诉。\"}}]}}, {\"object\": \"block\", \"id\": \"f4edb02a-54bf-4403-8f5a-d29d9fcec48d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6bffeeef-5306-4deb-8ddf-189f7502ee2a\"}, \"created_time