  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"84c1df4b-124e-4d52-8b63-4450cdd3ecc6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不用等检验报告才立案；奶粉无中文标签本身就能立案，边诉边补报告。\"}}]}}, {\"object\": \"block\", \"id\": \"f25903e3-40cf-4aca-820e-1b009fb7bc97\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"卖家经营异常时，平台责任要更早评估、更早发书面催告，不要等到快开庭才补。\"}}]}}, {\"object\": \"block\", \"id\": \"3df55a56-d288-456d-8d06-b522ef3db421\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"从第一天就按 E1、E2……编号管理证据，后面写诉状、质证、上诉都省事。\"}}]}}, {\"object\": \"block\", \"id\": \"d188e530-6fcd-49c1-811d-727b6126f7ab\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"八、二审接下来大概要准备啥\"}}]}}, {\"object\": \"block\", \"id\": \"6941f019-c031-4c6c-8b90-f484e4a8dfbc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"先拿上诉状副本，确认答辩期（通常收到后 15 日，以通知为准）。\"}}]}}, {\"object\": \"block\", \"id\": \"de9d38c6-b3af-4b78-8b4d-6cfd5cab92bd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"答辩状只守一审认定：十倍、无中文标签、茶含非法添加；不新增无关争点。\"}}]}}, {\"object\": \"block\", \"id\": \"3cb45857-5157-414f-8de6-d7fb941d6d58\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据重组：一审判决书 + 一审证据目录 + E1/E2/E3/E4/E5/E9/E13/E14；不要全部重交。\"}}]}}, {\"object\": \"block\", \"id\": \"c017af51-f7df-4f56-88c9-e3922247627a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"JY-008 报告如出来，作为补充证据；一审已认定茶含非法添加，报告不是必需。\"}}]}}, {\"object\": \"block\", \"id\": \"c27a5576-f094-47da-81db-bede0482dc73\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"可能书面审理，也可能开庭；等通知，准备一页纸口头意见。\"}}]}}, {\"object\": \"block\", \"id\": \"a02489e3-b284-41b1-84f6-9c79502b3a71\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二审判决/调解后：申请生效证明、催款；不付在 2 年内申请执行。\"}}]}}, {\"object\": \"block\", \"id\": \"798c5d3d-fa37-4bba-8284-32af33ffa105\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"九、给身边人的一页纸清单\"}}]}}, {\"object\": \"block\", \"id\": \"418f3baf-7fa4-464d-882d-7a10b642276e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"买/收：订单、支付、页面、聊天、开箱视频、快递面单、包装、实物，全部留。\"}}]}}, {\"object\": \"block\", \"id\": \"d7a0fdc7-948c-432f-8655-eff221ebf963\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"出问题：书面投诉，不退货、不寄回、不拆封、不签放弃权利。\"}}]}}, {\"object\": \"block\", \"id\": \"d04ce1c9-b8cb-47ab-873e-6c94727885c0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"就医：发票、病历、费用明细；写清“食用—症状—就诊”时间线。\"}}]}}, {\"object\": \"block\", \"id\": \"32448590-51c7-40ad-85d0-11e648b15311\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"检验：CMA/CNAS、范围覆盖、独立、固定收费、不与结果挂钩。\"}}]}}, {\"object\": \"block\", \"id\": \"1a2e6c3e-3d61-4201-8cad-1bd0b053b8ea\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"a9edd3f8-e04f-468c-8e4e-5090790f6f69\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"起诉：收货地法院；食品安全十倍，不是三倍；平台作为后备。\"}}]}}, {\"object\": \"block\", \"id\": \"16b24bbf-9cc6-471d-8ed1-db